import { sports, schools, teams, createGames, news, regions } from './data.js';
import { rankTeams, filterTeams, predict, advanceGames, escapeHtml as esc, loadFavorites, csvForTeams } from './domain.js';
const $ = s => document.querySelector(s);
const paths = {
  overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  rankings:'<path d="M8 21V11H3v10m13 0V3h-5v18m13 0V8h-5v13"/>',
  games:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m3 0h2"/>',
  teams:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',
  news:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M7 8h10M7 12h4m-4 4h10m-3-4h3"/>',
  favorites:'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3L12 17.4l-5.6 3 1.1-6.3L3 9.6l6.3-.9Z"/>',
  football:'<path d="M20.7 3.3C23 12 12 23 3.3 20.7 1 12 12 1 20.7 3.3Z"/><path d="m8 16 8-8m-8 3 5 5m-2-8 5 5M4 16l4 4M16 4l4 4"/>',
  basketball:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3v18M5.5 5.5c7 2 6 11 13 13m0-13c-7 2-6 11-13 13"/>',
  volleyball:'<circle cx="12" cy="12" r="9"/><path d="m12 12 8-5m-8 5V3m0 9-8 5M7 4c-2 6 0 10 5 13m9-6c-5-4-10-4-14-2m4 12c4-3 6-7 6-12"/>',
  soccer:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 4-2 6H9l-2-6 5-4Zm0 0V3m5 8 4-2m-6 8 3 3m-9-3-3 3m1-9L3 9"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',
};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.overview}</svg>`;
const pages = { overview:['Overview','Big games. Bigger Texas','From Friday night lights to state titles. Find your next team to follow.'], rankings:['Rankings','Let the game do the talking','Explore sport-specific ratings, records, and recent form.'], games:['Scores','Your next game starts here','Simulated live scores, final results, and upcoming matchups.'], teams:['Teams','Every team has a story','From your hometown to the whole state. Find your team.'], news:['News','More than a scoreboard','Game previews, season outlooks, and team stories. All articles are demo content.'], favorites:['My teams','Your teams. All in one place','Save your teams in this browser and pick up where you left off.'] };
const state={ view:'overview',sport:'football',classification:'all',region:'all',gender:'all',query:'',gameFilter:'all',games:createGames(),running:true,updated:null,modal:null };
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw new Error('Storage unavailable');}};}
state.favorites=loadFavorites(storage,new Set(teams.map(t=>t.id)));
const teamById = id => teams.find(t=>t.id===id);
const sportName = id => sports.find(s=>s.id===id)?.name || id;
const selected = () => filterTeams(rankTeams(teams.filter(t=>t.sport===state.sport)),state);
const selectedGames = () => { const ids=new Set(selected().map(t=>t.id));return state.games.filter(g=>g.sport===state.sport&&(ids.has(g.homeId)||ids.has(g.awayId))); };
const crest=(t,big=false)=>`<span class="crest ${big?'big':''}" style="--team:${t.color}" aria-hidden="true">${t.initials}</span>`;
const star=t=>`<button class="fav ${state.favorites.has(t.id)?'saved':''}" data-action="favorite" data-id="${t.id}" aria-label="${state.favorites.has(t.id)?'Unfollow':'Follow'} ${t.name}" aria-pressed="${state.favorites.has(t.id)}">${state.favorites.has(t.id)?'★':'☆'}</button>`;
const form=t=>`<span class="form" aria-label="Last five games: ${t.form.map(s=>s==='W'?'Win':'Loss').join(', ')}">${t.form.map(s=>`<span class="${s==='L'?'loss':''}">${s}</span>`).join('')}</span>`;
const change=t=>{const d=t.previousRank-t.rank;return `<span class="change ${d>0?'up':d<0?'down':'flat'}" aria-label="${d===0?'Rank unchanged':`${d>0?'Up':'Down'} ${Math.abs(d)} ${Math.abs(d)===1?'place':'places'}`}">${d>0?'↗ '+d:d<0?'↘ '+Math.abs(d):'—'}</span>`;};
function empty(title='No teams found',text='Try another sport, region, or search term.',favorites=false){return `<div class="empty"><div class="empty-icon">${favorites?'☆':'⌕'}</div><h3>${title}</h3><p>${text}</p><button class="secondary-button" data-action="${favorites?'explore':'reset-filters'}">${favorites?'Explore teams':'Clear filters'}</button></div>`;}
function renderNav(){ $('#nav').innerHTML=Object.entries(pages).map(([id,p])=>`<a href="#${id}" class="nav-item ${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(id)}<span>${p[0]}</span>${id==='favorites'?`<span class="count">${state.favorites.size}</span>`:''}</a>`).join(''); }
function renderShell(){renderNav();const p=pages[state.view];$('#breadcrumb').textContent=p[0];$('#page-title').innerHTML=esc(p[1])+'<span>.</span>';$('#page-subtitle').textContent=p[2];$('#sports').innerHTML=sports.map(s=>`<button class="sport-tab ${state.sport===s.id?'active':''}" data-action="sport" data-id="${s.id}" aria-pressed="${state.sport===s.id}">${icon(s.icon,18)}${s.name}</button>`).join('');$('.reset-filters').hidden=!(state.query||state.classification!=='all'||state.region!=='all'||state.gender!=='all');document.title=`${p[0]} · Texas High School Sports`;} 
function scoreCard(g){const h=teamById(g.homeId),a=teamById(g.awayId);return `<button class="score-card" data-action="game" data-id="${g.id}" aria-label="View ${h.name} vs. ${a.name}"><div class="score-head"><span class="${g.status==='live'?'live-tag':'final-tag'}">${g.status==='live'?'<span class="live-dot"></span> SIMULATED LIVE':g.status==='final'?'FINAL':'UPCOMING'}</span><span>${g.status==='live'?g.stage:g.date+' · '+g.time}</span></div><div class="team-line">${crest(h)}<span class="name">${h.name}</span><span class="score">${g.homeScore??'—'}</span></div><div class="team-line">${crest(a)}<span class="name">${a.name}</span><span class="score">${g.awayScore??'—'}</span></div><div class="context"><span>${h.classification} / ${a.classification} · ${sportName(g.sport)} · ${g.sport==='volleyball'?'sets':'score'}</span><span>Game center ↗</span></div></button>`;}
function streamControls(){return `<div class="stream-controls"><span class="last-update">${state.updated?'Updated '+state.updated:'Demo clock'}</span><button data-action="toggle-stream">${state.running?'Ⅱ Pause demo':'▷ Resume demo'}</button><button data-action="tick" aria-label="Advance simulated scores">↻</button></div>`;}
function rankingPanel(list,limit){const subset=limit?list.slice(0,limit):list;return `<section class="panel"><div class="panel-header"><h2>State power rankings<small> ${sports.find(s=>s.id===state.sport).short}</small></h2><span class="scope-chip">Unofficial · Demo</span></div>${subset.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Rank</th><th scope="col">Team / School</th><th scope="col" class="class-column">Class</th><th scope="col">Record</th><th scope="col">Rating</th><th scope="col">Change</th><th scope="col" class="form-column">Last 5</th><th scope="col"><span aria-label="Follow">☆</span></th></tr></thead><tbody>${subset.map(t=>`<tr><td><span class="rank ${t.rank<=3?'top':''}">${String(t.rank).padStart(2,'0')}</span></td><td><button class="table-team" data-action="team" data-id="${t.id}">${crest(t)}<span><strong>${t.name}</strong><small>${t.city} · ${t.mascot}</small></span></button></td><td class="class-column">${t.classification}</td><td>${t.wins}–${t.losses}</td><td><span class="rating">${t.rating.toFixed(1)}</span></td><td>${change(t)}</td><td class="form-column">${form(t)}</td><td>${star(t)}</td></tr>`).join('')}</tbody></table></div>`:empty()}<div class="panel-bottom"><span>${subset.length} / ${list.length} teams · State ranks retained</span><button data-action="${limit?'all-rankings':'method'}">${limit?'Full rankings →':'Rating methodology ↗'}</button></div></section>`;}
function forecastCard(){const list=selected();if(list.length<2)return `<section class="mini-panel"><h3>Matchup forecast</h3><p>Select at least two teams in the same sport by adjusting your filters.</p></section>`;const [h,a]=list;const p=predict(h,a);return `<section class="forecast"><div class="eyebrow"><span>MATCHUP SPOTLIGHT</span><span>★ DEMO FORECAST</span></div><h2>A matchup worth watching</h2><p>${sportName(state.sport)} · Top two rated teams · Demo matchup</p><div class="forecast-teams"><div class="forecast-team">${crest(h,true)}<strong>${h.name}</strong><small>${h.wins}–${h.losses} · ${h.classification}</small></div><span class="versus">VS</span><div class="forecast-team">${crest(a,true)}<strong>${a.name}</strong><small>${a.wins}–${a.losses} · ${a.classification}</small></div></div><div class="predicted-score">${p.homeScore} <span style="color:#809276">:</span> ${p.awayScore}</div><div class="predicted-caption">Demo predicted ${state.sport==='volleyball'?'sets':'score'} / NOT A REAL RESULT</div><div class="probability"><span>Home win chance <strong>${p.homeWin}%</strong></span><span>Away win chance <strong>${p.awayWin}%</strong></span></div><div class="probability-bar"><span style="width:${p.homeWin}%"></span></div><p class="disclaimer">Rule-based demo using sample ratings. Not backtested.</p><button data-action="compare">Build a matchup ${icon('arrow',13)}</button></section>`;}
const artLabels={field:'FRIDAY NIGHT',court:'NEXT UP',net:'ALL IN',pitch:'GAME ON'};
function newsCard(n){return `<button class="news-card" data-action="article" data-id="${n.id}"><div class="news-art ${n.art}" data-label="${artLabels[n.art]}" aria-hidden="true"><span class="art-caption">LONESTAR / DEMO EDITORIAL</span></div><div class="news-copy"><span class="news-tag">${n.tag} · ${sportName(n.sport)}</span><h3>${n.title}</h3><p>${n.summary}</p><div class="news-meta"><small>${n.time}</small><span>↗</span></div></div></button>`;}
function relevantNews(){const ids=new Set(selected().map(t=>t.schoolId));return news.filter(n=>n.sport===state.sport&&ids.has(n.schoolId));}
function renderOverview(){const list=selected(), games=selectedGames();const live=games.filter(g=>g.status==='live');const topGames=[...live,...games.filter(g=>g.status!=='live')].slice(0,3);const avg=list.length?(list.reduce((a,t)=>a+t.rating,0)/list.length).toFixed(1):'—';const related=relevantNews();return `<section><div class="section-heading"><h2><span class="live-dot"></span> Scoreboard <small>AROUND THE STATE</small></h2>${streamControls()}</div><div class="live-grid">${topGames.length?topGames.map(scoreCard).join(''):empty('No games found','Adjust your filters to see demo matchups.')}</div></section><section class="stats" aria-label="Filtered team statistics"><div class="stat"><div class="stat-label">Demo teams</div><div class="stat-value">${list.length}<small>teams</small></div></div><div class="stat"><div class="stat-label">Simulated live</div><div class="stat-value">${String(live.length).padStart(2,'0')}<small>games</small></div></div><div class="stat"><div class="stat-label">Avg. demo rating</div><div class="stat-value">${avg}<small>/ 100</small></div></div><div class="stat"><div class="stat-label">Following</div><div class="stat-value">${state.favorites.size}<small>${state.favorites.size===1?'team':'teams'}<span class="desktop"> · this browser</span></small></div></div></section><div class="content-grid">${rankingPanel(list,6)}<aside class="right-rail">${forecastCard()}<section class="mini-panel"><h3>Go beyond the rankings ↗</h3><p>Each sport has its own ratings. Explore records, recent form, and rating history to follow a team’s season.</p><button data-action="method">How ratings & predictions work →</button></section></aside></div><section class="news-section"><div class="section-heading"><h2>Beyond the score <small>STORIES & SPOTLIGHTS</small></h2><button class="section-link" data-action="all-news">All stories →</button></div><div class="news-grid">${related.length?[...related,...news.filter(n=>!related.includes(n)).slice(0,2)].map(newsCard).join(''):empty('No demo stories found','Stories follow your selected sport, team, and region filters.')}</div></section>`;}
function renderRankings(){return `<div class="view-intro"><div><h2>Every win carries weight.</h2><p>${sportName(state.sport)} · ${selected().length} demo teams · Separate rankings by sport and gender</p></div><button class="primary-button" data-action="export">${icon('download',15)}Export CSV</button></div>${rankingPanel(selected())}<p class="method-note">Ratings are preset demo values. W = win, L = loss. Filtered teams retain their original statewide rank. Ratings, records, and changes are fictional examples.</p>`;}
function renderGames(){const list=selectedGames().filter(g=>state.gameFilter==='all'||g.status===state.gameFilter);return `<div class="view-intro"><div><h2>From kickoff to the final whistle.</h2><p>Demo schedule: Oct 16 & Oct 23, 2026 · All times Central (CT)</p></div>${streamControls()}</div><div class="view-tabs" aria-label="Game status">${[['all','All games'],['live','Simulated live'],['final','Final'],['upcoming','Upcoming']].map(([id,name])=>`<button data-action="game-filter" data-id="${id}" class="${state.gameFilter===id?'active':''}" aria-pressed="${state.gameFilter===id}">${name}</button>`).join('')}</div><div class="games-list">${list.length?list.map(scoreCard).join(''):empty('No games found','Choose a different game status or adjust your filters.')}</div><p class="method-note">The simulator advances every 8 seconds. Volleyball updates its rally label only. Pause or step through the demo at any time. No real score feed is connected.</p>`;}
function teamCard(t){return `<article class="team-card"><div class="team-card-head">${crest(t,true)}${star(t)}</div><h3><button style="padding:0;text-align:left;font-weight:inherit" data-action="team" data-id="${t.id}">${t.name}</button></h3><p>${t.city} · ${regions[t.region]} · ${t.classification}</p><div class="team-card-stat"><div><strong>#${t.rank}</strong><small>Demo state rank</small></div><div><strong>${t.rating.toFixed(1)}</strong><small>Demo rating</small></div><div><strong>${t.wins}–${t.losses}</strong><small>Record</small></div></div><button class="detail-button" data-action="team" data-id="${t.id}"><span>${sportName(t.sport)} · ${t.gender==='boys'?'Boys':'Girls'} Varsity</span><span>Team profile →</span></button></article>`;}
function renderTeams(favorites=false){const list=selected().filter(t=>!favorites||state.favorites.has(t.id));return `<div class="view-intro"><div><h2>${favorites?'Keep your teams close.':'Find your home team.'}</h2><p>${favorites?'Following in this view:':'In this view:'} ${list.length} ${list.length===1?'team':'teams'}${favorites?' · Saved in this browser only':''}</p></div>${!favorites?'<button class="primary-button" data-action="compare">Compare teams ↗</button>':''}</div><div class="team-grid">${list.length?list.map(teamCard).join(''):favorites?empty('No followed teams in this view','Tap ☆ next to a team to follow it, or change your sport and filters to see saved teams.',true):empty()}</div>`;}
function renderNews(){const list=relevantNews();return `<div class="view-intro"><div><h2>The stories behind the schools.</h2><p>Demo articles for your current sport and filters · Fictional content</p></div></div><div class="news-grid all-news">${list.length?list.map(newsCard).join(''):empty('No demo stories found','Try a different sport, region, or search term.')}</div><p class="method-note">The full app will include sources, publication dates, and original article links. These fictional stories demonstrate the news and team-profile experience.</p>`;}
function renderContent(){const fn={overview:renderOverview,rankings:renderRankings,games:renderGames,teams:()=>renderTeams(),news:renderNews,favorites:()=>renderTeams(true)};$('#content').innerHTML=fn[state.view]();}
function render(){renderShell();renderContent();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function openModal(html,type,id){state.modal={type,id};$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();state.modal=null;}
function teamModal(id){const t=rankTeams(teams.filter(t=>t.sport===teamById(id).sport)).find(t=>t.id===id);const games=state.games.filter(g=>g.homeId===id||g.awayId===id);const values=t.history;const points=values.map((v,i)=>`${32+i*66},${115-(v-60)*2.1}`).join(' ');openModal(`<div class="modal-eyebrow">TEAM PROFILE / Fictional team</div><div class="modal-team-head">${crest(t,true)}<div><h2 class="modal-title" id="modal-title">${t.name}</h2><p>${t.city} · ${regions[t.region]} · ${t.classification} · ${sportName(t.sport)} ${t.gender==='boys'?'Boys':'Girls'} varsity</p></div>${star(t)}</div><div class="modal-stat-row"><div><strong>#${t.rank}</strong><small>Demo state rank</small></div><div><strong>${t.rating}</strong><small>Demo rating</small></div><div><strong>${t.wins}–${t.losses}</strong><small>Demo record</small></div></div><div class="modal-body"><h3>Rating history <span style="font-size:9px;font-weight:400">Last 8 weeks · Demo data</span></h3><svg class="chart" viewBox="0 0 530 140" role="img" aria-label="Eight weeks of demo ratings: ${values.join(', ')}"><path d="M30 35H500M30 75H500M30 115H500" stroke="#e2e8d7" stroke-dasharray="4 5"/><polygon points="32,130 ${points} 494,130" fill="#718d4c15"/><polyline points="${points}" fill="none" stroke="${t.color}" stroke-width="2.5"/>${values.map((v,i)=>`<circle cx="${32+i*66}" cy="${115-(v-60)*2.1}" r="3" fill="${t.color}"/>`).join('')}</svg><div class="chart-labels"><span>Week 1</span><span>Week 8</span></div><h3>Recent form</h3>${form(t)}<h3>Schedule & results</h3>${games.map(g=>`<button class="modal-game" style="width:100%;text-align:left" data-action="game" data-id="${g.id}"><span>${g.date} · vs ${teamById(g.homeId===id?g.awayId:g.homeId).name}</span><strong>${g.status==='upcoming'?'Upcoming':`${g.homeScore} : ${g.awayScore}`} ↗</strong></button>`).join('')}<div class="injury-note"><strong>Injuries & availability: Unknown</strong><br>This demo does not collect player health information. The full app will show only sourced reports confirmed by schools, teams, or reliable reporting, with timestamps.</div></div>`, 'team',id);}
function gameModal(id){const g=state.games.find(g=>g.id===id),h=teamById(g.homeId),a=teamById(g.awayId);openModal(`<div class="modal-eyebrow">GAME CENTER / SIMULATED GAME</div><h2 class="modal-title" id="modal-title">${h.name} vs ${a.name}</h2><p class="modal-subtitle">${g.date} · ${g.time} CT · ${g.venue} · Fictional fixture</p><div class="compare-result"><div class="result-names"><button data-action="team" data-id="${h.id}">${crest(h)} ${h.name}</button><button data-action="team" data-id="${a.id}">${crest(a)} ${a.name}</button></div><div class="predicted-score">${g.homeScore??'—'} : ${g.awayScore??'—'}</div><p style="text-align:center">${g.status==='live'?`Simulated live · ${g.stage}`:g.status==='final'?'Final · Demo result':'Upcoming · Demo schedule'}${g.sport==='volleyball'?' · sets':''}</p></div><div class="modal-body"><h3>Game details</h3><p>Scores come from the browser’s demo simulator, not a real game feed. Both teams are fictional.</p><div class="modal-game"><span>Home demo rating</span><strong>${h.rating}</strong></div><div class="modal-game"><span>Away demo rating</span><strong>${a.rating}</strong></div><h3>Before the game</h3><p>Compare these teams to explore demo score predictions and win probabilities.</p><button class="primary-button" data-action="compare-game" data-id="${id}">View demo prediction →</button></div>`, 'game',id);}
function compareModal(homeId,awayId){const list=selected();if(list.length<2&&!homeId){toast('Adjust your filters to include two teams in the same sport.');return;}const candidates=homeId?rankTeams(teams.filter(t=>t.sport===teamById(homeId).sport)):list;const home=homeId||candidates[0].id,away=awayId||candidates[1].id;const options=selectedId=>candidates.map(t=>`<option value="${t.id}" ${t.id===selectedId?'selected':''}>${t.name}</option>`).join('');openModal(`<div class="modal-eyebrow">MATCHUP LAB / DEMO PREDICTION</div><h2 class="modal-title" id="modal-title">Who has the edge?</h2><p class="modal-subtitle">Choose two teams in the same sport to explore a matchup.</p><div class="compare-selects"><label>Home team<select id="compare-home" aria-label="Home team">${options(home)}</select></label><label>Away team<select id="compare-away" aria-label="Away team">${options(away)}</select></label></div><div id="compare-output"></div><div class="modal-body"><h3>How is this prediction calculated?</h3><p>Win probability = 1 / (1 + exp(−(rating difference + 1.5) / 11)). Scores use a sport-specific baseline and rating difference. Volleyball predicts final sets in a best-of-five match.</p><p>This is an illustrative formula, not a model trained or backtested on historical games. Soccer uses a two-outcome display and does not model draws. These are not real game predictions.</p></div>`, 'compare');renderComparison();}
function renderComparison(){try{const h=teamById($('#compare-home').value),a=teamById($('#compare-away').value),p=predict(h,a);$('#compare-output').innerHTML=`<div class="compare-result"><div class="result-names"><span>${esc(h.name)}</span><span>${esc(a.name)}</span></div><div class="predicted-score">${p.homeScore} : ${p.awayScore}</div><p style="text-align:center">Demo predicted ${h.sport==='volleyball'?'sets':'score'} · Not backtested</p><div class="probability"><span>Home win chance <strong>${p.homeWin}%</strong></span><span>Away win chance <strong>${p.awayWin}%</strong></span></div><div class="probability-bar"><span style="width:${p.homeWin}%"></span></div></div>`;}catch(e){$('#compare-output').innerHTML=`<p class="error" role="alert">${esc(e.message)}</p>`;}}
function aboutModal(method=false){openModal(`<div class="modal-eyebrow">LONESTAR / PRODUCT DEMO</div><h2 class="modal-title" id="modal-title">${method?'Know what’s behind the numbers.':'Every team has a place here.'}</h2><div class="modal-body"><p>Texas High School Sports is a working Texas high school sports prototype with ${schools.length} fictional schools, ${teams.length} demo varsity teams, and ${state.games.length} sample games across four sports.</p><h3>About the data</h3><p>All schools, records, scores, ratings, and articles are fictional fixtures. They are not provided by UIL, MaxPreps, or any other data service. No live score, news, or injury feed is connected. October basketball and soccer schedules are for demonstration only.</p><h3>Rankings & ratings</h3><p>Each sport is ranked by preset rating, then wins and school name. Boys and girls teams are stored separately. This demo includes boys football, boys basketball, girls volleyball, and girls soccer; other combinations show an empty state. Class and region filters retain statewide ranks. Historical trends and records are independent display samples, not inputs to these ratings.</p><h3>Scores & predictions</h3><p>Simulated scores advance every 8 seconds and can be paused, stepped forward, or reset. Predictions use a fixed rating-difference rule that has not been backtested. Volleyball displays sets; soccer does not model draws.</p><h3>Local storage</h3><p>Only followed team IDs are saved in this browser. There are no accounts, backend database, or cross-device sync. Reloading resets simulated scores. No real player profiles or health information are collected.</p><h3>What’s next</h3><p>The source separates the interface, demo fixtures, and calculation logic, with local startup scripts and tests. Future development can add licensed data providers, a database, and accounts.</p><button class="secondary-button" data-action="reset-demo">Reset demo scores (keep followed teams)</button></div>`, 'about');}
function articleModal(id){const n=news.find(n=>n.id===id);openModal(`<div class="modal-eyebrow">DEMO EDITORIAL / FICTIONAL STORY</div><h2 class="modal-title" id="modal-title">${n.title}</h2><p class="modal-subtitle">${n.tag} · ${sportName(n.sport)} · ${n.time}</p><div class="news-art article-art ${n.art}" data-label="${artLabels[n.art]}" aria-hidden="true"></div><div class="modal-body"><p>${n.summary}</p><p>${n.body}</p><p>Source: Texas High School Sports product demo. This is a fictional article.</p><button class="primary-button" data-action="team" data-id="${n.schoolId}-${n.sport}">View featured team →</button></div>`, 'article',id);}
function tick(){state.games=advanceGames(state.games);state.updated=new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(new Date())+' CT';if(state.view==='overview'||state.view==='games')renderContent();if(state.modal?.type==='game')gameModal(state.modal.id);}
function favorite(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);try{storage.setItem('lonestar:favorites',JSON.stringify([...state.favorites]));toast(state.favorites.has(id)?'Team followed':'Team unfollowed');}catch{toast('Updated for this session. Your browser blocked persistent storage.');}renderNav();renderContent();if(state.modal?.type==='team')teamModal(state.modal.id);}
function resetFilters(){state.query='';state.classification=state.region=state.gender='all';$('#search').value='';for(const id of ['classification','region','gender'])$('#'+id).value='all';render();}
function navigate(){const v=location.hash.slice(1);const next=pages[v]?v:'overview';const changed=state.view!==next;state.view=next;render();if(changed)window.scrollTo({top:0,behavior:'instant'});}
function exportCsv(){const blob=new Blob([csvForTeams(selected())],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`texas-high-school-sports-${state.sport}-rankings.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported the filtered demo rankings');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;const actions={sport:()=>{state.sport=id;render();},favorite:()=>favorite(id),team:()=>teamModal(id),game:()=>gameModal(id),article:()=>articleModal(id),'close-modal':closeModal,about:()=>aboutModal(),method:()=>aboutModal(true),compare:()=>compareModal(),'compare-game':()=>{const g=state.games.find(g=>g.id===id);compareModal(g.homeId,g.awayId);},'toggle-stream':()=>{state.running=!state.running;renderContent();toast(state.running?'Demo scores resumed':'Demo scores paused');},tick:()=>{tick();toast('Advanced one demo step');},'game-filter':()=>{state.gameFilter=id;renderContent();},'reset-filters':resetFilters,'all-rankings':()=>{location.hash='rankings';},'all-news':()=>{location.hash='news';},explore:()=>{resetFilters();location.hash='teams';},'reset-demo':()=>{state.games=createGames();state.updated=null;renderContent();closeModal();toast('Demo scores reset. Followed teams kept.');},export:exportCsv};actions[action]?.();});
$('#search').addEventListener('input',e=>{state.query=e.target.value;renderShell();renderContent();});
for(const id of ['classification','region','gender'])$('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render();});
$('#modal').addEventListener('change',e=>{if(e.target.id.startsWith('compare-'))renderComparison();});
$('#modal').addEventListener('close',()=>state.modal=null);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});
window.addEventListener('hashchange',navigate);
setInterval(()=>{if(state.running&&!document.hidden)tick();},8000);
navigate();
